import{_ as l,o as e,c as a,am as o}from"./chunks/framework._FJXuPhs.js";const g=JSON.parse('{"title":"基础知识","description":"","frontmatter":{"title":"基础知识","excerpt":"摘要","date":"2026-06-01 17:09:24","updated":"2026-06-01 17:09:24"},"headers":[],"relativePath":"数据库/基础知识.md","filePath":"数据库/基础知识.md","lastUpdated":null}'),r={name:"数据库/基础知识.md"};function i(s,t,n,d,c,h){return e(),a("div",null,[...t[0]||(t[0]=[o('<h3 id="数据库基础" tabindex="-1">数据库基础 <a class="header-anchor" href="#数据库基础" aria-label="Permalink to &quot;数据库基础&quot;">​</a></h3><hr><p>数据库基础知识包含了数据库设计、管理和操作的核心概念。</p><p>常见的一些概念👇</p><ul><li>数据库和数据库管理系统（DBMS）</li><li>数据模型（关系模型与非关系模型）</li><li>数据库设计 <ul><li>ER图</li><li>数据库范式</li></ul></li><li>元组, 码, 候选码, 主码, 外码, 主属性, 非主属性</li><li>主键和外键</li><li>为什么不推荐使用外键与级联</li><li>存储过程</li><li>数据库设计</li><li>字符集</li></ul><hr><h4 id="sql-结构化查询语言" tabindex="-1">SQL（结构化查询语言） <a class="header-anchor" href="#sql-结构化查询语言" aria-label="Permalink to &quot;SQL（结构化查询语言）&quot;">​</a></h4><ul><li><strong>数据定义语言（DDL）</strong>：定义数据库结构，包括CREATE、ALTER、DROP等命令。</li><li><strong>数据操纵语言（DML）</strong>：用于数据访问和处理，包括INSERT、UPDATE、DELETE、SELECT等命令。</li><li><strong>数据控制语言（DCL）</strong>：用于权限和事务控制，包括GRANT、REVOKE、BEGIN TRANSACTION等。</li></ul><h4 id="ddl-和-dml" tabindex="-1">DDL 和 DML <a class="header-anchor" href="#ddl-和-dml" aria-label="Permalink to &quot;DDL 和 DML&quot;">​</a></h4><p><strong>DDL</strong>代表数据定义语言（Data Definition Language），它用于定义数据库结构，包括创建、修改和删除数据库对象。</p><p><strong>DML</strong>代表数据操作语言（Data Manipulation Language），它用于操作和管理数据库中的数据，包括查询、插入、更新和删除数据</p><h4 id="drop、delete-与-truncate-区别" tabindex="-1">drop、delete 与 truncate 区别? <a class="header-anchor" href="#drop、delete-与-truncate-区别" aria-label="Permalink to &quot;drop、delete 与 truncate 区别?&quot;">​</a></h4><ul><li>drop 移除整个表结构，包括其数据和表定义 不能回滚（DDL)</li><li>delete 删除表中的一行或多行记录 能回滚(DML)</li><li>truncate 删除表中的所有记录 不能回滚（DDL)</li></ul><p>执行速度：一般来说：<code>drop</code> &gt; <code>truncate</code> &gt; <code>delete</code></p><p>在MySQL中，<code>DROP</code>、<code>DELETE</code>和<code>TRUNCATE</code>都是用于移除数据的命令，但它们在用法和影响上有明显的区别：</p><blockquote><ol><li>DELETE</li></ol></blockquote><ul><li><strong>用途</strong>：<code>DELETE</code>用于删除表中的一行或多行记录。</li><li><strong>特点</strong>： <ul><li>可以带有<code>WHERE</code>子句，提供了条件删除的功能。</li><li>影响的行数会记录在事务日志中，因此可以回滚。</li><li>触发器（如果有的话）会被激活。</li><li>较慢，特别是在删除大量数据时，因为它逐行删除。</li></ul></li><li><strong>示例</strong>：<code>DELETE FROM table_name WHERE condition;</code></li></ul><blockquote><ol start="2"><li>TRUNCATE</li></ol></blockquote><ul><li><strong>用途</strong>：<code>TRUNCATE</code>用于删除表中的所有记录。</li><li><strong>特点</strong>： <ul><li>不能带有<code>WHERE</code>子句，它总是删除表中的所有记录。</li><li>执行速度比<code>DELETE</code>快，因为它不逐行删除数据，而是直接移除数据页。</li><li>不记录详细的事务日志，只记录重建空表的操作，因此无法回滚（在某些数据库系统中，<code>TRUNCATE</code>是事务安全的，并且可以回滚）。</li><li>重置表的自增计数器（如果有的话）。</li><li>不触发触发器。</li></ul></li><li><strong>示例</strong>：<code>TRUNCATE TABLE table_name;</code></li></ul><blockquote><ol start="3"><li>DROP</li></ol></blockquote><ul><li><strong>用途</strong>：<code>DROP</code>用于移除整个表结构，包括其数据和表定义。</li><li><strong>特点</strong>： <ul><li>删除表的结构及其数据，释放存储空间。</li><li>不能回滚（一旦执行，表就完全消失了）。</li><li>不触发触发器。</li><li>在删除大量数据且不再需要该表时使用。</li></ul></li><li><strong>示例</strong>：<code>DROP TABLE table_name;</code></li></ul><blockquote><p>总结</p></blockquote><ul><li><strong>删除数据行</strong>：如果需要删除部分数据行，使用<code>DELETE</code>。若需删除所有数据行且表结构仍需保留，使用<code>TRUNCATE</code>。</li><li><strong>删除表</strong>：如果要删除整个表及其数据，使用<code>DROP</code>。</li><li><strong>性能考虑</strong>：当处理大量数据时，<code>TRUNCATE</code>比<code>DELETE</code>更高效。</li><li><strong>事务和回滚</strong>：<code>DELETE</code>操作可以回滚，而<code>TRUNCATE</code>和<code>DROP</code>在大多数情况下不能。</li></ul><p>选择使用哪个命令取决于具体的需求，如是否需要保留表结构、是否需要条件删除或是否关注性能优化。</p><h4 id="数据库设计通常分为哪几步" tabindex="-1">数据库设计通常分为哪几步? <a class="header-anchor" href="#数据库设计通常分为哪几步" aria-label="Permalink to &quot;数据库设计通常分为哪几步?&quot;">​</a></h4><ol><li><strong>需求分析</strong> : 分析用户的需求，包括数据、功能和性能需求。</li><li><strong>概念结构设计</strong> : 主要采用 E-R 模型进行设计，包括画 E-R 图。</li><li><strong>逻辑结构设计</strong> : 通过将 E-R 图转换成表，实现从 E-R 模型到关系模型的转换。</li><li><strong>物理结构设计</strong> : 主要是为所设计的数据库选择合适的存储结构和存取路径。</li><li><strong>数据库实施</strong> : 包括编程、测试和试运行。</li><li><strong>数据库的运行和维护</strong> : 系统的运行与数据库的日常维护</li></ol><hr><p>参考</p><ul><li><a href="https://javaguide.cn/database/basis.html" target="_blank" rel="noreferrer">https://javaguide.cn/database/basis.html</a></li></ul><hr><p>SQL 语法基础知识： <a href="https://javaguide.cn/database/sql/sql-syntax-summary.html" target="_blank" rel="noreferrer">https://javaguide.cn/database/sql/sql-syntax-summary.html</a></p><p><strong>SQL常见面试题</strong></p><ul><li><a href="https://javaguide.cn/database/sql/sql-questions-01.html" target="_blank" rel="noreferrer">https://javaguide.cn/database/sql/sql-questions-01.html</a></li><li><a href="https://javaguide.cn/database/sql/sql-questions-02.html" target="_blank" rel="noreferrer">https://javaguide.cn/database/sql/sql-questions-02.html</a></li><li><a href="https://javaguide.cn/database/sql/sql-questions-03.html" target="_blank" rel="noreferrer">https://javaguide.cn/database/sql/sql-questions-03.html</a></li><li><a href="https://javaguide.cn/database/sql/sql-questions-04.html" target="_blank" rel="noreferrer">https://javaguide.cn/database/sql/sql-questions-04.html</a></li><li><a href="https://javaguide.cn/database/sql/sql-questions-05.html" target="_blank" rel="noreferrer">https://javaguide.cn/database/sql/sql-questions-05.html</a></li></ul><hr><h3 id="nosql" tabindex="-1">NoSQL <a class="header-anchor" href="#nosql" aria-label="Permalink to &quot;NoSQL&quot;">​</a></h3><p>NoSQL（Not Only SQL 的缩写）泛指非关系型的数据库，主要针对的是键值、文档以及图形类型数据存储。并且，NoSQL 数据库天生支持分布式，数据冗余和数据分片等特性，旨在提供可扩展的高可用高性能数据存储解决方案。</p><p>NoSQL 数据库代表：HBase、Cassandra、MongoDB、Redis。</p><h4 id="sql-和-nosql-有什么区别" tabindex="-1">SQL 和 NoSQL 有什么区别？ <a class="header-anchor" href="#sql-和-nosql-有什么区别" aria-label="Permalink to &quot;SQL 和 NoSQL 有什么区别？&quot;">​</a></h4><table tabindex="0"><thead><tr><th></th><th>SQL 数据库</th><th>NoSQL 数据库</th></tr></thead><tbody><tr><td>数据存储模型</td><td>结构化存储，具有固定行和列的表格</td><td>非结构化存储。文档：JSON 文档，键值：键值对，宽列：包含行和动态列的表，图：节点和边</td></tr><tr><td>发展历程</td><td>开发于 1970 年代，重点是减少数据重复</td><td>开发于 2000 年代后期，重点是提升可扩展性，减少大规模数据的存储成本</td></tr><tr><td>例子</td><td>Oracle、MySQL、Microsoft SQL Server、PostgreSQL</td><td>文档：MongoDB、CouchDB，键值：Redis、DynamoDB，宽列：Cassandra、 HBase，图表：Neo4j、 Amazon Neptune、Giraph</td></tr><tr><td>ACID 属性</td><td>提供原子性、一致性、隔离性和持久性 (ACID) 属性</td><td>通常不支持 ACID 事务，为了可扩展、高性能进行了权衡，少部分支持比如 MongoDB 。不过，MongoDB 对 ACID 事务 的支持和 MySQL 还是有所区别的。</td></tr><tr><td>性能</td><td>性能通常取决于磁盘子系统。要获得最佳性能，通常需要优化查询、索引和表结构。</td><td>性能通常由底层硬件集群大小、网络延迟以及调用应用程序来决定。</td></tr><tr><td>扩展</td><td>垂直（使用性能更强大的服务器进行扩展）、读写分离、分库分表</td><td>横向（增加服务器的方式横向扩展，通常是基于分片机制）</td></tr><tr><td>用途</td><td>普通企业级的项目的数据存储</td><td>用途广泛比如图数据库支持分析和遍历连接数据之间的关系、键值数据库可以处理大量数据扩展和极高的状态变化</td></tr><tr><td>查询语法</td><td>结构化查询语言 (SQL)</td><td>数据访问语法可能因数据库而异</td></tr></tbody></table><h4 id="nosql-数据库有哪些类型" tabindex="-1">NoSQL 数据库有哪些类型？ <a class="header-anchor" href="#nosql-数据库有哪些类型" aria-label="Permalink to &quot;NoSQL 数据库有哪些类型？&quot;">​</a></h4><p>NoSQL 数据库主要可以分为下面四种类型：</p><ul><li><strong>键值</strong>：键值数据库是一种较简单的数据库，其中每个项目都包含键和值。这是极为灵活的 NoSQL 数据库类型，因为应用可以完全控制 value 字段中存储的内容，没有任何限制。Redis 和 DynanoDB 是两款非常流行的键值数据库。</li><li><strong>文档</strong>：文档数据库中的数据被存储在类似于 JSON（JavaScript 对象表示法）对象的文档中，非常清晰直观。每个文档包含成对的字段和值。这些值通常可以是各种类型，包括字符串、数字、布尔值、数组或对象等，并且它们的结构通常与开发者在代码中使用的对象保持一致。MongoDB 就是一款非常流行的文档数据库。</li><li><strong>图形</strong>：图形数据库旨在轻松构建和运行与高度连接的数据集一起使用的应用程序。图形数据库的典型使用案例包括社交网络、推荐引擎、欺诈检测和知识图形。Neo4j 和 Giraph 是两款非常流行的图形数据库。</li><li><strong>宽列</strong>：宽列存储数据库非常适合需要存储大量的数据。Cassandra 和 HBase 是两款非常流行的宽列存储数据库。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20231119123254.png" alt="image.png"></p><hr><p>参考</p><ul><li><a href="https://javaguide.cn/database/nosql.html" target="_blank" rel="noreferrer">https://javaguide.cn/database/nosql.html</a></li><li><a href="https://www.ibm.com/cn-zh/topics/nosql-databases" target="_blank" rel="noreferrer">https://www.ibm.com/cn-zh/topics/nosql-databases</a></li><li><a href="https://zhuanlan.zhihu.com/p/345342966" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/345342966</a></li></ul>',46)])])}const p=l(r,[["render",i]]);export{g as __pageData,p as default};
